// Üretilen dosya: tool/ozgun/uret.py. Sınav Hazırlık · TYT Türkçe: sözcükte ve cümlede anlam (her soru kendi cümlesini içerir) (kolay).
const ozExam1Kolay = <(String, String, List<String>, String)>[
  ('Aşağıdaki cümlelerin hangisinde "ağır" sözcüğü gerçek anlamıyla kullanılmıştır?', 'Bu bavul çok ağır, tek başıma taşıyamam.', ['Ağır sözleri yüzünden herkes ona küstü.', 'Yaşlı adam ağır ağır merdivenleri çıktı.', 'Ağır bir hastalık geçirdiği için okula gelemedi.'], 'Gerçek anlamda "ağır", tartıda çok çeken demektir; bavulun ağırlığı bu anlamı karşılar. Diğerlerinde kırıcı, yavaş ve ciddi anlamları vardır.'),
  ('Aşağıdaki cümlelerin hangisinde "kırmak" sözcüğü gerçek anlamda kullanılmıştır?', 'Çocuk topla oynarken mutfak camını kırdı.', ['Annesinin kalbini kırmamak için o akşam hiç sesini çıkarmadı.', 'Bu yıl ihracatta rekor kırdık.', 'Fiyatı biraz kırarsanız hemen alırım.'], 'Camın parçalanması, sözcüğün ilk ve temel anlamıdır. Kalp kırmak mecaz, rekor kırmak deyim, fiyat kırmak ise indirim yapmak anlamındadır.'),
  ('Aşağıdaki cümlelerin hangisinde "tatlı" sözcüğü mecaz anlamda kullanılmıştır?', 'Kapıyı tatlı bir gülümsemeyle açtı.', ['Bayramda tatlı olarak baklava yaptık.', 'Bu karpuz çok tatlıymış.', 'Çayıma fazla şeker atınca tatlı oldu.'], 'Gülümsemenin tadı olmaz; burada "tatlı" hoşa giden, sevimli anlamında mecazdır. Diğerlerinde tat duyusuyla ilgili gerçek anlam vardır.'),
  ('Bir kişinin tavrını anlatırken sıcaklık bildiren bir sıfatın aktarıldığı cümle hangisidir? (Sözcük: "soğuk")', 'Yeni müdür herkese karşı soğuk davranıyordu.', ['Soğuk suyla yüzünü yıkadı.', 'Kışın bu köyde hava çok soğuk olur, yollar kapanır.', 'Buzdolabından soğuk bir ayran aldı.'], 'Davranışın sıcaklığı ölçülemez; "soğuk davranmak" ilgisiz ve mesafeli olmak anlamında mecazdır.'),
  ('Aşağıdaki cümlelerin hangisinde "göz" sözcüğü yan anlamda kullanılmıştır?', 'Dolabın üst gözüne havluları yerleştirdik.', ['Gözüne toz kaçınca ağlamaya başladı.', 'Kedinin gözleri karanlık odada iki ışık gibi parlıyordu.', 'Doktor, gözlerini muayene etti.'], 'Dolabın bölmesine "göz" denmesi, organın adının biçim benzerliğiyle başka bir nesneye aktarılmasıdır; bu yan anlamdır.'),
  ('Organ adı olan "ağız", hangi cümlede bir yerin girişini karşılayacak biçimde başka bir varlığa aktarılmıştır?', 'Mağaranın ağzı çalılarla kapanmıştı.', ['Ağzında sakız çiğneyerek konuşuyordu.', 'Bebek ağzını açıp esnedi.', 'Diş hekimi ağzımı iyice açmamı istedi.'], 'Mağaranın girişi, organ olan ağza benzetilerek adlandırılmıştır; bu, somut bir varlığın benzerlik yoluyla kazandığı yan anlamdır.'),
  ('"Etek" sözcüğü aşağıdakilerin hangisinde, bir giysi adı olmanın dışında, benzerlik yoluyla kazanılmış bir anlamda kullanılmıştır?', 'Dağın eteğinde küçük bir köy kurulmuştu.', ['Annesi ona yeni bir etek dikti.', 'Eteğinin ucu çamura bulanmıştı.', 'Okul formasında lacivert etek giyiliyordu.'], 'Dağın alt kısmı, giysinin bedenin altında kalan bölümüne benzetilerek "etek" diye adlandırılır; bu yan anlamdır.'),
  ('Vücudumuzdaki bir organın adı, hangi cümlede biçim benzerliğiyle bir eşyanın parçasına ad olmuştur? (Sözcük: "diş")', 'Tarağın birkaç dişi kırılmıştı.', ['Yemekten sonra dişlerini fırçaladı.', 'Bebeğin ilk dişi çıkmış.', 'Soğuk su içince dişi sızladı.'], 'Tarağın sivri uçları, biçim benzerliğiyle "diş" diye anılır. Diğer üç cümlede ağızdaki organ kastedilmiştir.'),
  ('"Çıkmak" sözcüğü aşağıdaki cümlelerin hangisinde "ortaya konmak, yayımlanmak" anlamında kullanılmıştır?', 'Şairin yeni kitabı geçen hafta çıktı.', ['Sabah erkenden evden çıktı.', 'Elbisenin lekesi yıkayınca çıktı.', 'Dağın zirvesine iki saatlik bir yürüyüşle çıktık.'], 'Kitabın çıkması, yayımlanması demektir. Diğerlerinde bir yerden ayrılmak, yok olmak ve yükselmek anlamları vardır.'),
  ('Aşağıdaki cümlelerin hangisinde "geçmek" sözcüğü "sınavda başarılı olmak" anlamında kullanılmıştır?', 'Bu dönem bütün derslerden geçti.', ['Köprüden geçerken aşağıya baktı.', 'Ağrısı, doktorun verdiği ilaçla birlikte geçti.', 'Aradan üç yıl geçti.'], 'Derslerden geçmek, başarılı olup üst sınıfa ya da sonraki aşamaya ulaşmaktır. Diğerlerinde bir yerin üstünden aşmak, sona ermek ve zamanın akması anlatılır.'),
  ('Aşağıdaki cümlelerin hangisinde "ince" sözcüğü "ayrıntıları gözeten, nazik" anlamında kullanılmıştır?', 'Doğum günümü hatırlaması çok ince bir davranıştı.', ['İnce bir hırka almasına rağmen akşam serinliğinde üşüdü.', 'Pastanın üstüne ince bir krema sürdü.', 'Kâğıdı ince ince kesip süs yaptı.'], 'Davranışın inceliği, düşünceli ve nazik olmayı anlatır; mecaz anlamdır. Diğerlerinde kalınlığı az olma anlamı vardır.'),
  ('"Kalıtım konusunu işlerken öğretmenimiz baskın ve çekinik genlerin farkını örneklerle açıkladı." cümlesinde terim olarak kullanılan "çekinik" sözcüğü hangi bilim dalına aittir?', 'Biyoloji', ['Kimya', 'Coğrafya bilimi', 'Fizik'], '"Çekinik", biyolojide etkisini baskın gen yanında gösteremeyen geni anlatan bir terimdir. Diğer sözcükler gündelik dilin sözcükleridir.'),
  ('"Açı" sözcüğü aşağıdakilerin hangisinde geometri terimi olarak kullanılmıştır?', 'Üçgenin iç açılarının toplamı 180 derecedir.', ['Olaya bir de onun açısından bakmalısın.', 'Fotoğrafçı en uygun açıyı bulmak için yere çömeldi.', 'Yazar konuya farklı bir açıdan yaklaşmış.'], 'Üçgenin iç açıları, geometride iki ışının ortak başlangıç noktasında oluşturduğu şekli anlatır. Diğerlerinde "bakış yönü, görüş" anlamı vardır.'),
  ('Aşağıdaki cümlelerin hangisinde "faiz" sözcüğü ekonomi alanına özgü anlamıyla kullanılmıştır?', 'Bankadan aldığı krediye yüksek faiz ödüyordu.', ['Bu faiz değil, düpedüz bir lütuftu.', 'Faiz sözcüğünü sözlükte arayan çocuk anlamını görünce şaşırdı.', 'Aramızda faiz diye bir sorun hiç olmadı.'], 'Faiz, borç verilen paranın karşılığı olarak alınan ek tutardır; kredi için ödenen faiz bu terim anlamıdır.'),
  ('"Yazar, öyküsünde iç monoloğu ustaca kullanarak kahramanın zihnindeki çatışmayı yansıtmış." cümlesindeki "iç monolog" hangi alana özgü bir terimdir?', 'Edebiyat', ['Hukuk', 'Tıp', 'Ekonomi ve maliye'], 'İç monolog, bir kahramanın kendi kendine, zihninden geçirdiklerinin aktarılmasıdır ve edebiyat terimidir.'),
  ('"Uzun bir yolculuktan sonra bitap düşmüştü." cümlesindeki "bitap" sözcüğünün eş anlamlısı aşağıdakilerden hangisidir?', 'yorgun', ['öfkeli', 'sevinçli', 'meraklı'], '"Bitap", gücü kalmamış, çok yorgun demektir; eş anlamlısı "yorgun"dur.'),
  ('Aşağıdaki sözcük çiftlerinin hangisi eş anlamlı değildir?', 'cesur - temkinli', ['ihtiyar - yaşlı', 'kırmızı - al renk', 'yanıt - cevap'], 'Cesur, korkusuzca davranan; temkinli ise ölçülü ve dikkatli davranan demektir; bu iki sözcük eş anlamlı değildir. Diğer çiftler aynı anlamı karşılar.'),
  ('"Bu konuda onunla münakaşa etmenin bir yararı olmadığını sonunda anladım." cümlesindeki "münakaşa" yerine anlam değişmeden hangisi getirilebilir?', 'tartışma', ['anlaşma', 'yardımlaşma', 'danışma'], 'Münakaşa, karşılıklı ve çoğu zaman sert biçimde tartışmaktır; Türkçe karşılığı "tartışma"dır.'),
  ('"Okulun bahçesindeki çınar asırlardır orada duruyordu." cümlesinde "asırlardır" sözcüğünün yerine hangisi kullanılırsa anlam korunur?', 'yüzyıllardır', ['yıllardır', 'haftalardır', 'on yıllardır'], '"Asır" yüz yıllık süre demektir; anlamı koruyan karşılığı "yüzyıl"dır. Yıl ve on yıl süreyi kısaltarak anlamı değiştirir.'),
  ('"Toplantıda alınan kararlar, katılımcıların çoğunluğu tarafından kabul edildi." cümlesindeki "kabul" sözcüğünün karşıt anlamlısı hangisidir?', 'ret', ['onay', 'rıza', 'kayıt'], 'Kabul, bir şeyi uygun bulup almak; ret ise geri çevirmektir. Onay ve rıza kabulün eş anlamlılarıdır.'),
  ('"Yaşlı adam, cimri komşusunun tersine son derece ... biriydi." cümlesinde boş bırakılan yere anlamca hangisi getirilmelidir?', 'cömert', ['tutumlu', 'titiz', 'çekingen'], '"Tersine" ifadesi karşıtlık kurar; "cimri"nin karşıtı "cömert"tir. Tutumlu, cimriye yakın bir anlam taşır.'),
  ('Aşağıdaki çiftlerin hangisinde sözcükler arasında karşıtlık ilişkisi yoktur?', 'mutlu - memnun', ['cesaret - korku', 'alçak - yüksek', 'dost - düşman'], 'Mutlu ve memnun, anlamca birbirine yakın sözcüklerdir. Diğer çiftler karşıt anlam taşır.'),
  ('"Bu yaz tatilinde kırk gün boyunca köyde kaldık, sonra şehre döndük." cümlesindeki "yaz" sözcüğüyle sesteş olan kullanım hangisidir?', 'Adresini şu kâğıda yaz.', ['Bu yaz çok sıcak geçti.', 'Yaz aylarında deniz kenarına gideriz.', 'Yazın en uzun günü haziranda yaşanır.'], 'Mevsim adı olan "yaz" ile "yazmak" eyleminin emir kipi "yaz" sesteştir. Diğer seçeneklerde yine mevsim anlamı vardır.'),
  ('"Çay" sözcüğü hangi cümlede "küçük akarsu" anlamıyla yer almıştır?', 'Köyün kenarından akan çayda balık tutardık.', ['Kahvaltıda iki bardak çay içti.', 'Rize\'de yaş çay toplama mevsimi mayıs ayında başladı.', 'Çay demlenirken sohbete daldık.'], 'Akarsu olarak "çay" ile içecek adı olan "çay" sesteştir; ilk cümlede akarsu anlamı vardır.'),
  ('"Sevgi, korku, umut ve özlem" sözcüklerinin ortak özelliği nedir?', 'Duyularla algılanamayan kavramlar olmaları', ['Yalnızca şiirde kullanılan sözcükler olmaları', 'Tamamının başka dillerden Türkçeye geçmiş sözcükler olması', 'Birer eylem bildiren sözcükler olmaları'], 'Bu sözcüklerin karşıladığı kavramlar görülemez, dokunulamaz; zihinde var olur. Bu yüzden soyut anlamlıdır.'),
  ('Aşağıdaki sözcük gruplarının hangisinde sözcükler genelden özele doğru sıralanmıştır?', 'canlı - hayvan - kuş - serçe', ['serçe - kuş - hayvan - canlı', 'kuş - canlı - serçe - hayvanlar', 'hayvan - serçe - canlı - kuş'], '"Canlı" en kapsamlı kavramdır; hayvan, kuş ve serçe sırasıyla kapsamı daralan kavramlardır.'),
  ('"Bahçede çiçekler açmış, bir köşede de laleler boy göstermişti." cümlesindeki "çiçek" ve "lale" sözcükleri arasında nasıl bir anlam ilişkisi vardır?', 'Genel - özel', ['Eş anlam', 'Karşıt anlamlılık', 'Sesteşlik'], 'Çiçek, laleyi de içine alan geniş bir kavramdır; lale ise çiçeğin bir türüdür. Bu genel-özel ilişkisidir.'),
  ('Aşağıdakilerin hangisinde güzel adlandırma örneği vardır?', 'Dedesi geçen kış rahmetli olmuştu.', ['Dedesi bahçede ağaç dikiyordu.', 'Dedesi köyün en yaşlısıydı.', 'Dedesiyle her yaz göl kıyısında balığa giderdi.'], '"Ölmek" yerine "rahmetli olmak" demek, acı bir kavramı yumuşatarak anlatmaktır. Bu, güzel adlandırma örneğidir.'),
  ('Aşağıdaki cümlelerin hangisinde doğadaki bir sesin yansımasından türemiş bir sözcük yoktur?', 'Akşam olunca kuşlar ağaçlara döndü.', ['Dere, şırıl şırıl akıyordu.', 'Kapı gıcırdayarak açıldı.', 'Yağmur camlara pıtır pıtır vuruyordu.'], 'Şırıl, gıcırdamak ve pıtır sözcükleri seslerin yansımasıyla oluşmuştur. Dördüncü cümlede yansıma sözcük yoktur.'),
  ('"Misafirler gelmeden önce evi silip süpürdük." cümlesindeki "silip süpürmek" ikilemesi hangi anlamı katmıştır?', 'Her yeri iyice temizlemek', ['Evdeki eşyaların yerini baştan sona değiştirmek', 'Evi kısa sürede terk etmek', 'Misafirleri kapıda karşılamak'], 'Yakın anlamlı iki eylemin bir arada kullanılması, temizliğin eksiksiz yapıldığını vurgular.'),
  ('"Ali, hiç durmadan çalışarak sınavlara hazırlanıyordu." cümlesindeki "hiç durmadan" sözünün yerine anlamca en yakın ikileme hangisidir?', 'durup dinlenmeden', ['ara sıra', 'yavaş yavaş, dura dura', 'bata çıka'], '"Durup dinlenmeden", ara vermeden, sürekli anlamına gelir. "Ara sıra" zaman zaman demektir; diğerleri de anlamı değiştirir.'),
  ('"Ağzı kulaklarına varmak" deyiminin anlamı aşağıdakilerden hangisidir?', 'Çok sevinmek', ['Çok konuşmak ve sır tutamamak', 'Herkese bağırmak', 'Şaşkınlıktan donup kalmak'], 'Sevinçten geniş geniş gülümsemeyi abartılı biçimde anlatan bu deyim "çok sevinmek" anlamına gelir.'),
  ('"Etekleri zil çalmak" deyimi aşağıdaki duygulardan hangisini anlatır?', 'Büyük bir sevinci', ['Derin bir öfkeyi', 'Kaygı ve korkuyu', 'Yorgunluk ve bıkkınlığı'], 'Bu deyim, sevincini gizleyemeyecek kadar mutlu olmayı anlatır.'),
  ('"Kılı kırk yarmak" deyimini en iyi açıklayan seçenek hangisidir?', 'Bir işte en ince ayrıntıları bile gözetmek', ['Bir işi yarım bırakıp başka işe geçmek', 'Bir işi bitirmek için aceleyle, özensizce davranmak', 'Bir işi başkasının üzerine yıkmak'], 'Bu deyim, aşırı titizlik göstermeyi ve ayrıntı üzerinde fazlasıyla durmayı anlatır.'),
  ('"Pireyi deve yapmak" deyimi hangi davranışı eleştirir?', 'Küçük bir olayı büyütmeyi', ['Bir işi çok yavaş yapmayı', 'Başkalarına gereğinden fazla güvenmeyi', 'Verilen sözü tutmamayı'], 'Önemsiz bir şeyi çok önemliymiş gibi gösterip abartmak bu deyimle anlatılır.'),
  ('"Ayağını yorganına göre uzatmak" deyiminin anlamı hangisidir?', 'Harcamalarını gelirine göre ayarlamak', ['Her işe ağırdan alarak başlamak', 'Yatmadan önce plan yapmak', 'Kimseye danışmadan, yalnızca kendi bildiğine göre karar vermek'], 'Deyim, kazancının üstünde harcama yapmamayı, olanaklarına göre yaşamayı öğütler.'),
  ('"Yıllarca emek verdiği proje bir anda ... ; bütün hayalleri yıkıldı." cümlesinde boşluğa getirilecek deyim hangisidir?', 'suya düştü', ['göze girdi', 'kulak kabarttı', 'dile düştü'], '"Suya düşmek", bir tasarı ya da umudun gerçekleşmemesi demektir; cümlenin sonundaki hayallerin yıkılması bunu doğrular.'),
  ('"Damlaya damlaya göl olur." atasözü aşağıdaki düşüncelerden hangisini öğütler?', 'Küçük birikimlerin zamanla büyük sonuçlar doğuracağını', ['Suyun israf edilmemesi gerektiğini', 'Büyük işlerin tek seferde bitirilmesi gerektiğini', 'Yağmurun doğadaki bütün canlılar için çok önemli olduğunu'], 'Atasözü, az da olsa düzenli biriktirilen şeylerin zamanla büyük bir varlığa dönüşeceğini anlatır.'),
  ('"Sakla samanı, gelir zamanı." atasözüyle anlatılmak istenen hangisidir?', 'Değersiz görünen bir şey bir gün işe yarayabilir.', ['Hayvanlara kışın yeterince yem verilmelidir.', 'Zamanı iyi kullanan kişi çok kazanır.', 'Saklanan şeyler bir süre sonra bozulur ve atılmak zorunda kalınır.'], 'Samanın önemsiz görülse de gün gelip gerekebileceği anlatılarak, elimizdekini hor görmememiz öğütlenir.'),
  ('"Ağaç yaşken eğilir." atasözü hangi konuya ilişkin bir öğüt verir?', 'Eğitimin küçük yaşta başlaması gerektiğine', ['Fidanların düzgün büyümesi için desteklenmesine', 'Yaşlıların gençlere örnek olmasına', 'Ağaçların sonbaharda budanmasına'], 'Ağaç benzetmesiyle insanın küçük yaşta daha kolay biçimlendirileceği, eğitimin erken başlaması gerektiği anlatılır.'),
  ('Aşağıdaki atasözlerinden hangisi "tek başına iş yapılamaz, birlik gerekir" düşüncesini işler?', 'Bir elin nesi var, iki elin sesi var.', ['Sütten ağzı yanan yoğurdu üfleyerek yer.', 'Ak akçe kara gün içindir.', 'Komşu komşunun külüne muhtaçtır ve her işte ona danışır.'], 'İki elin birlikte ses çıkarabileceği benzetmesiyle dayanışmanın gücü anlatılır.'),
  ('"Kolay gelsin." sözü hangi durumda söylenir?', 'Çalışmakta olan birini selamlarken', ['Bir yemeğin ardından ev sahibine teşekkür ederken', 'Yolculuğa çıkan birini uğurlarken', 'Hasta birine geçmiş olsun derken'], '"Kolay gelsin", iş yapmakta olan birine iyi dilekle seslenirken kullanılan kalıplaşmış bir sözdür.'),
  ('Aşağıdaki kalıplaşmış sözlerden hangisi, başkasının başına gelen bir sıkıntı karşısında söylenmez?', 'Ellerinize sağlık.', ['Geçmiş olsun.', 'Başınız sağ olsun.', 'Allah sabır versin.'], '"Ellerinize sağlık", birinin hazırladığı bir şey için teşekkür ederken söylenir; diğerleri acı ya da sıkıntı karşısında kullanılır.'),
  ('"Hayırlı olsun" sözü aşağıdaki durumların hangisinde söylenmeye en uygundur?', 'Bir arkadaşın yeni bir işe başladığını öğrenince', ['Bir tanıdığın ağır hastalandığını öğrenince', 'Birinin yakınını kaybettiğini duyunca', 'Biri sana bir fincan kahve ısmarladığında teşekkür ederken'], '"Hayırlı olsun", yeni bir başlangıcın iyiliklere vesile olması dileğiyle söylenen kalıplaşmış bir sözdür.'),
  ('"Çalmak" sözcüğü aşağıdakilerin hangisinde "bir müzik aletinden ses çıkarmak" anlamında kullanılmıştır?', 'Dedem akşamları bağlama çalıp türkü söylerdi.', ['Kapıyı çalan postacıydı, elinde bir paket vardı.', 'Hırsız, bisikletimi kapının önünden çaldı.', 'Gün boyu güneşte kalınca rengi beyaza çaldı.'], 'Bağlama çalmak, müzik aletinden ses çıkarmaktır. Kapı çalmak vurmak, bisiklet çalmak hırsızlık, renk için çalmak ise andırmak anlamındadır.'),
  ('"Almak" eylemi aşağıdaki cümlelerin hangisinde "bir yeri ele geçirmek" anlamındadır?', 'Osmanlı ordusu kaleyi kırk gün süren kuşatmadan sonra aldı.', ['Pazardan iki kilo domates aldı.', 'Bu salon yüz kişi alır.', 'Sınavdan yüksek not aldı, bunu duyan ailesi çok sevindi.'], 'Bir kaleyi almak, savaşarak orayı ele geçirmektir. Diğerlerinde satın almak, sığdırmak ve kazanmak anlamları vardır.'),
  ('"Düşmek" sözcüğü aşağıdaki cümlelerin hangisinde "değerce azalmak" anlamında kullanılmıştır?', 'Hasattan sonra pazarda domates fiyatları düştü.', ['Bisikletten düşünce dizi kanadı.', 'Bu yıl bayram hafta sonuna düşüyor.', 'Yolunuz bu tarafa düşerse bize uğrayın, çok seviniriz.'], 'Fiyatın düşmesi, değerin azalmasıdır. Diğer cümlelerde yere yıkılmak, denk gelmek ve yolun bir yerden geçmesi anlatılır.'),
  ('"Yaşlı adam yıllar önce olan o olayı hâlâ unutamamıştı." cümlesindeki "unutamamak" sözünün yerine hangisi getirilirse anlam değişmez?', 'aklından çıkaramamak', ['kafasına takmamak', 'umursamamak, önem vermemek', 'bir kenara bırakmak'], '"Aklından çıkaramamak", bir şeyi sürekli düşünmek, unutamamak demektir. Diğerleri önemsememeyi anlatır.'),
  ('"Yeni gelen öğretmen kısa sürede öğrencilerin gönlünü kazandı." cümlesindeki altı çizilmesi istenen "gönlünü kazanmak" sözünün yerine hangisi kullanılabilir?', 'sevgisini elde etmek', ['onlara gönül koymak', 'kendini onlara acındırmak', 'onlarla yarışıp öne geçmek'], 'Birinin gönlünü kazanmak, onun sevgi ve beğenisini kazanmaktır.'),
  ('"Kardeşim bu haberi duyunca küplere bindi." cümlesinde "küplere binmek" yerine anlamca en uygun söz hangisidir?', 'çok öfkelenmek', ['çok sevinmek', 'şaşkına dönmek', 'üzüntüsünden ağlamak ve kimseyle konuşmamak'], '"Küplere binmek", çok öfkelenmek demektir.'),
  ('"Arkadaşının yaptığı iyiliği hiç unutmadı, ona her zaman minnet duydu." cümlesindeki düşünceyi en iyi karşılayan söz hangisidir?', 'iyilik bilmek', ['nankörlük etmek', 'gözden çıkarmak', 'ağzının payını vermek'], 'Yapılan iyiliği unutmayıp karşısındakine minnet duymak "iyilik bilmek" ile anlatılır. Nankörlük bunun tersidir.'),
  ('"Bizim sokaktaki fırının ekmekleri her sabah taptaze çıkar." cümlesinde "taptaze" sözcüğünün yerine anlamca hangisi getirilebilir?', 'yeni pişmiş', ['bayatlamış', 'soğumuş', 'kurumuş ve sertleşmiş'], '"Taptaze" ekmek için yeni pişmiş, bayatlamamış demektir.'),
  ('"Kaza sonrası yaralılar, ivedilikle en yakın hastaneye kaldırıldı." cümlesindeki "ivedilikle" sözcüğünün anlamı nedir?', 'acele olarak', ['dikkatle', 'sırayla', 'ağır ağır, acele etmeden'], '"İvedilik", acele, çabukluk demektir; "ivedilikle" de acele olarak anlamına gelir.'),
  ('"Bu tarihî çeşme, yıllardır bakımsız kaldığı için harabeye döndü; belediye onu yeniden ... ." cümlesinde boşluğa hangisi getirilmelidir?', 'onardı', ['yıktı', 'sattı', 'taşıdı'], 'Harabeye dönmüş bir yapı için belediyeden beklenen, onu onarmasıdır; "yeniden" sözcüğü de eski durumuna getirmeyi çağrıştırır.'),
  ('"Çekmek" sözcüğü hangi cümlede "bir sıkıntıya katlanmak" anlamında kullanılmıştır?', 'Gençliğinde çok yoksulluk çekmişti.', ['Halatı var gücüyle kendine doğru çekti.', 'Bu kumaş yıkanınca çeker, dikkatli ol.', 'Fotoğrafçı, düğünde yüzlerce fotoğraf çekti.'], 'Yoksulluk çekmek, yoksulluğun getirdiği sıkıntıya katlanmaktır. Diğerlerinde güç uygulamak, küçülmek ve fotoğraf almak anlamları vardır.'),
  ('"Gece boyunca yağan kar yüzünden okullar tatil edildi." cümlesinde yargılar arasında nasıl bir ilişki vardır?', 'Neden-sonuç ilişkisi', ['Amaç-sonuç ilişkisi', 'Koşul-sonuç ilişkisi', 'Karşılaştırma ilişkisi'], 'Okulların tatil edilmesi, kar yağmasının sonucudur; "yüzünden" edatı nedeni bildirir.'),
  ('"Düzenli çalışırsan sınavda başarılı olursun." cümlesinde başarılı olmak hangi şarta bağlanmıştır?', 'Düzenli çalışmaya', ['Sınavın kolay olmasına', 'Öğretmenin yardım etmesine', 'Sınavdan önce iyi dinlenmeye'], '"-sa/-se" eki koşul bildirir; başarı, düzenli çalışma koşuluna bağlanmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde gerçekleşmesi bir şarta bağlanmış bir yargı yoktur?', 'Sabah erkenden kalkıp yürüyüşe çıktı.', ['İstersen bu akşam bize gel.', 'Biraz daha dikkatli olsaydın düşmezdin.', 'Vaktim olursa sergiyi gezeceğim.'], 'İlk cümle gerçekleşmiş bir olayı şartsız bildirir. Diğerlerinde "istersen", "olsaydın", "olursa" koşul kurar.'),
  ('"Romandaki karakterler, yazarın önceki eserlerine göre daha derinlikli işlenmiş." cümlesinde karşılaştırma nasıl yapılmıştır?', 'Yazarın kendi eserleri arasında', ['İki farklı yazarın eserleri arasında', 'Roman ile şiir türü arasında', 'Yazar ile okur arasında'], 'Yazarın yeni romanı, "önceki eserlerine göre" ifadesiyle kendi eski eserleriyle kıyaslanmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde bir niteliğin en üst derecede olduğu bildirilmiştir?', 'Sınıfın en çalışkan öğrencisi bu yıl da birinci oldu.', ['Bu kitap ötekinden biraz daha kalın.', 'Kardeşim benden daha uzun boylu.', 'Bu yol, o yoldan daha kısa ama daha engebeli ve tehlikeli.'], '"En" sözcüğü niteliği en üst dereceye çıkarır, yani üstünlük bildirir. Diğerlerinde iki varlık arasında karşılaştırma vardır.'),
  ('Aşağıdaki cümlelerin hangisi kanıtlanabilir bir bilgi içermediği için öznel bir yargıdır?', 'Bu filmin müzikleri insanın içine işliyor.', ['Film, iki saat on dakika sürüyor.', 'Filmin çekimleri İstanbul\'da yapıldı.', 'Film, bir romandan uyarlanmıştır.'], 'Müziğin insanın içine işlemesi kişiden kişiye değişen bir izlenimdir. Süre, çekim yeri ve uyarlanma bilgisi doğrulanabilir.'),
  ('"Bence", "kanımca", "bana göre" gibi sözlerin cümlede bulunması genellikle neyi gösterir?', 'Yargının kişisel bir görüş olduğunu', ['Yargının bilimsel olarak kanıtlandığını', 'Cümlenin bir tanım bildirdiğini', 'Anlatılanın geçmişte kaldığını'], 'Bu sözler, söyleyenin kendi görüşünü belirttiğini gösterir ve yargıyı öznelleştirir.'),
  ('"Bu saatte yollar boş olduğuna göre yarım saate kadar orada oluruz herhalde." cümlesinde yargı nasıl bildirilmiştir?', 'Tahmine dayalı olarak', ['Kesin bir bilgi olarak', 'Bir öneri biçiminde', 'Yakınma yoluyla, söylenerek'], '"Herhalde" sözcüğü, konuşanın varış süresinden emin olmadığını, bir tahmin yürüttüğünü gösterir.'),
  ('"Kuşkusuz bu proje, kentin ulaşım sorununu büyük ölçüde çözecek." cümlesindeki "kuşkusuz" sözcüğü yargıya hangi anlamı katmaktadır?', 'Kesinlik', ['Olasılık', 'Pişmanlık', 'Yakınma'], '"Kuşkusuz", konuşanın yargısından emin olduğunu, yargıyı kesin olarak bildirdiğini gösterir.'),
  ('Aşağıdaki cümlelerin hangisinde olasılık anlamı "belki" sözcüğüyle sağlanmıştır?', 'Belki bu akşam bize uğrar, dedi annem.', ['Bu akşam bize kesinlikle uğrayacak.', 'Bu akşam bize uğradığı için sevindik.', 'Bize uğrayacaksa önceden telefonla haber versin.'], '"Belki", gerçekleşip gerçekleşmeyeceği bilinmeyen bir durumu anlatarak olasılık bildirir.'),
  ('Aşağıdaki cümlelerin hangisinde varsayım anlamı vardır?', 'Farz edelim ki bu yarışı kazandın, ödülü ne yapacaksın?', ['Bu zorlu yarışı kazandığın için seni yürekten kutluyorum.', 'Yarışı kazanmak için çok çalıştın.', 'Yarışı kazanan ödülünü yarın alacak.'], '"Farz edelim ki" kalıbı, gerçekleşmemiş bir durumu varmış gibi kabul ederek varsayım kurar.'),
  ('"Bu yıl da kitap fuarına gideceğiz." cümlesinden hangisi örtülü olarak anlaşılır?', 'Daha önce de kitap fuarına gidilmiştir.', ['Kitap fuarı ilk kez düzenlenmektedir.', 'Konuşan kitap okumayı sevmez.', 'Fuara gidilip gidilmeyeceği belirsizdir.'], '"Da" bağlacı, bu davranışın daha önce de yapıldığını sezdirir; bu, cümlenin örtülü anlamıdır.'),
  ('"Bu köyden çıkan biri zaten iyi bir yazar olamaz." cümlesinde nasıl bir yaklaşım vardır?', 'Ön yargı', ['Nesnel bir tespit', 'Olasılık bildiren bir öneri', 'Bir pişmanlık itirafı'], 'Kişinin yazarlığı, eserleri tanınmadan doğduğu yere göre peşinen yargılanmıştır; bu bir ön yargıdır.'),
  ('"Uykusuzluk çekiyorsan akşamları ekrana bakmayı bırakıp kitap okumayı dene." cümlesinde konuşanın amacı nedir?', 'Karşısındakine bir çözüm önermek', ['Karşısındakini sert bir dille eleştirmek', 'Geçmişte yaptığı bir hatadan dolayı pişmanlığını dile getirmek', 'Bir durumdan yakınmak'], 'Konuşan, uykusuzluk sorunu için bir yol göstermekte, öneride bulunmaktadır.'),
  ('Aşağıdaki cümlelerin hangisinde öneri anlamı yoktur?', 'Dün akşam yağmur yüzünden konsere gidemedik.', ['Yağmur yağıyorsa yanına bir şemsiye almalısın.', 'Konser bileti almadan önce salonun yerini öğrensen iyi olur.', 'Bence konserden önce bir şeyler yemelisin.'], 'İlk cümle yalnızca geçmişte yaşanan bir olayı bildirir. Diğerlerinde "-malısın", "iyi olur" gibi yapılarla yol gösterilmiştir.'),
  ('"Yeni başlayanlar, ilk günden uzun koşular yerine kısa yürüyüşlerle işe başlamalı." cümlesi hangi tür bir yargı bildirir?', 'Tavsiye', ['Yakınma', 'Pişmanlık', 'Ön yargı'], 'Cümle, yeni başlayanlara nasıl davranmaları gerektiği konusunda yol göstermektedir; bu bir tavsiyedir.'),
  ('"Yazar, olayları o kadar uzatmış ki okur, romanın ortasına gelmeden sıkılıyor." cümlesinde nasıl bir tutum vardır?', 'Olumsuz eleştiri', ['Olumlu eleştiri', 'Kesin bir bilgi aktarımı', 'Bir öneri ya da tavsiye'], 'Olayların gereksiz uzatılması ve okurun sıkılması, eserin eksik yönüne işaret eden olumsuz bir eleştiridir.'),
  ('"Bu kentte trafik her geçen gün çekilmez oluyor; işe gitmek saatlerimizi alıyor." cümlesinde hangi duygu ağır basmaktadır?', 'Yakınma', ['Övünme', 'Umut', 'Teşekkür'], 'Konuşan, trafiğin yarattığı sıkıntıdan şikâyet etmektedir; bu bir yakınmadır.'),
  ('Aşağıdaki cümlelerin hangisinde yakınma söz konusudur?', 'Komşunun köpeği her gece havlıyor, gözümüze uyku girmiyor.', ['Komşunun köpeği çok sevimli ve uslu bir hayvan.', 'Komşunun köpeğine her sabah mama veriyoruz.', 'Komşumuz, köpeğini her akşam yemekten sonra parkta gezdiriyor.'], 'Köpeğin havlaması yüzünden uyuyamamaktan şikâyet edilmektedir; diğer cümlelerde yakınma yoktur.'),
  ('"Keşke o gün arkadaşımın sözünü dinleseydim." cümlesinde anlatılan duygu hangisidir?', 'Pişmanlık', ['Yakınma', 'Övünme', 'Kararlılık'], '"Keşke ... -seydim" yapısı, geçmişte yapılmamış bir şey için duyulan pişmanlığı anlatır.'),
  ('"Bu çantada bütün dünyayı taşıyorsun sanki!" cümlesinde hangi anlatım biçimine başvurulmuştur?', 'Abartma', ['Kişileştirme', 'Tanımlama', 'Karşılaştırma ile kanıtlama'], 'Çantanın çok ağır ya da dolu olduğunu anlatmak için "bütün dünyayı taşımak" gibi gerçekleşmesi olanaksız bir anlatım kullanılmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde benzetme yapılmıştır?', 'Gözleri iki yıldız gibi parlıyordu.', ['Gökyüzünde binlerce yıldız parlıyordu.', 'Yıldızları izlemek için çatıya çıktık.', 'Yıldız kayarken bir dilek tuttu.'], 'Gözler parlaklık yönünden yıldızlara benzetilmiştir; diğer cümlelerde yıldız gerçek anlamıyla kullanılmıştır.'),
  ('"Aslan gibi bir delikanlı" söz öbeğinde delikanlı aslana hangi yönden benzetilmiştir?', 'Güç ve yiğitlik', ['Yeleli ve sarı olma', 'Ormanda yaşama', 'Çok uyuma ve tembellik'], 'Halk dilinde "aslan gibi" benzetmesi, güçlü, yiğit, sağlıklı olmayı anlatır.'),
  ('"Rüzgâr, pencereden içeri girip perdelerle oynuyordu." cümlesinde hangi söz sanatına başvurulmuştur?', 'Kişileştirme', ['Abartma', 'Benzetme edatıyla benzetme', 'Ad aktarması'], 'Rüzgâra "perdelerle oynamak" gibi insana özgü bir davranış yüklenmiştir; bu kişileştirmedir.'),
  ('"Bu şehir bir karınca yuvası; herkes bir yere yetişmeye çalışıyor." cümlesinde şehrin karınca yuvasına benzetilmesinin dayanağı hangisidir?', 'Kalabalık ve sürekli hareketli olması', ['Toprak altında kurulmuş olması', 'Küçük ve sessiz bir yer olması', 'Karıncaların bu şehirde öteki şehirlerden daha çok yaşaması'], 'Karınca yuvası, sürekli koşuşturan kalabalık bir topluluğu çağrıştırır; şehir bu yönden benzetilmiştir.'),
  ('Aşağıdaki cümlelerin hangisi bir kavramın ne olduğunu açıklayan bir tanım cümlesidir?', 'Ada, dört tarafı sularla çevrili kara parçasıdır.', ['Adalar, yazın tatilcilerle dolup taşar.', 'Bu küçük adaya yaz aylarında her gün iki vapur seferi yapılıyor.', 'Çocukluğumun en güzel yazları adada geçti.'], 'Tanım cümlesi bir kavramın temel niteliklerini "... dır" kalıbıyla açıklar; ada kavramı tanımlanmıştır.'),
  ('"Roman, olayların, kişilerin ve ortamların ayrıntılı biçimde anlatıldığı uzun soluklu bir edebî türdür." cümlesi için hangisi söylenebilir?', 'Bir türün temel özelliklerini sıralayarak tanım yapmaktadır.', ['Bir romanı okura önermektedir.', 'Bir romanı olumsuz yönleriyle eleştirmektedir.', 'İki edebî türü birbiriyle kıyaslayıp birini üstün tutmaktadır.'], 'Cümle, roman türünün ne olduğunu ve ayırt edici özelliklerini açıklayan bir tanımdır.'),
  ('Aşağıdaki cümlelerin hangisinde anlamca çelişki vardır?', 'Hiç tanımadığım bu adamı yıllardır tanıyorum.', ['Uzun yıllar görmediğim arkadaşımı hemen tanıdım.', 'Bu adamı yıllardır tanıyorum ama hâlâ çözemedim.', 'Onu ilk kez görmeme rağmen tanıdık geldi.'], '"Hiç tanımadığım" ile "yıllardır tanıyorum" yargıları birbirini yok eder; cümle mantıksal olarak çelişkilidir.'),
  ('"Bu işi yapmak için gereken zamanımız var." cümlesiyle anlamca en yakın cümle hangisidir?', 'Bu iş için yeterli vaktimiz bulunuyor.', ['Bu işi yapacak zamanımız hiç kalmadı.', 'Bu iş için daha fazla zamana ihtiyacımız olacak.', 'Bu işi yapmak zamanımızı boşa harcamaktır.'], '"Gereken zamanımız var" ile "yeterli vaktimiz bulunuyor" aynı yargıyı bildirir.'),
  ('"Kitaplar, insanın ufkunu genişletir." yargısına anlamca en yakın cümle hangisidir?', 'Okumak, insanın dünyaya bakışını zenginleştirir.', ['Kitaplar, insanı yalnızlaştırır.', 'Kitap okumak gözlerimizi yorar.', 'Kitapların fiyatı her geçen gün artıyor, okur sayısı azalıyor.'], '"Ufkunu genişletmek" ile "bakışını zenginleştirmek" aynı düşünceyi farklı sözlerle anlatır.'),
  ('"Bu yazarın öykülerinde, sıradan insanların ... yaşamları ustaca anlatılır; bu yüzden okur kendini onlarda bulur." cümlesinde boş bırakılan yere hangisi getirilmelidir?', 'gündelik', ['olağanüstü', 'masalsı', 'kahramanca'], 'Okurun kendini bulabilmesi için sıradan insanların günlük yaşamları anlatılmalıdır; "gündelik" bu bağlama uyar.'),
  ('"Bir dili iyi öğrenmenin yolu, o dili ... ." cümlesi aşağıdakilerin hangisiyle tamamlanırsa anlamca en uygun olur?', 'her fırsatta konuşmaya çalışmaktır', ['hiç kullanmadan yalnızca dinlemektir', 'yalnızca sözlüğünü ezberlemektir', 'öğrenmeye başlamadan bırakmaktır'], 'Cümle bir dili iyi öğrenmenin yolunu soruyor; en uygun ve tutarlı tamamlama, dili sürekli kullanmaktır.'),
  ('"Kar kalınlaştıkça köy yolları kapandı; bu yüzden ... ." cümlesi hangisiyle tamamlanmalıdır?', 'köylüler günlerce kente inemedi', ['köylüler her gün kente rahatça gidip geldi', 'köyün yolları genişletildi', 'yollara kar yağmadı'], '"Bu yüzden" bir sonuç bekler; yolların kapanmasının sonucu köylülerin kente inememesidir.'),
  ('"Bu filmi beğenmeyen yoktur." cümlesinin anlamca olumlu karşılığı hangisidir?', 'Bu filmi herkes beğenir.', ['Bu filmi kimse beğenmez.', 'Bu filmi bazıları beğenir.', 'Bu filmi beğenmek zordur.'], '"Beğenmeyen yok" demek, filmin herkesçe beğenildiğini söylemektir.'),
  ('"Bu dünyada dostsuz yaşanır mı?" sözde sorusunun anlatmak istediği yargı hangisidir?', 'Dostsuz yaşanamaz.', ['Dostsuz da yaşanabilir.', 'Dostlar zamanla değişir.', 'Dost bulmak kolaydır.'], 'Soru, yanıtı açık olan bir yargıyı (dostsuz yaşanamayacağını) vurgulamak için sorulmuştur.'),
  ('"Ressam, tablolarında ışığı öyle ustaca kullanıyor ki izleyici, resmin karşısında güneşi hissediyor." cümlesinde vurgulanan nedir?', 'Ressamın ışığı resme yansıtmadaki ustalığı', ['Tabloların büyük boyutlu olması', 'Ressamın yalnızca güneşi resmetmesi', 'İzleyicilerin güneşli günlerde müzeye gitmesi'], '"Öyle ustaca ... ki" yapısı, ışık kullanımındaki ustalığı ve bunun izleyicide yarattığı etkiyi vurgular.'),
  ('"Her yeni kitap, okuruna bir kapı aralar." cümlesinde "kapı aralamak" sözüyle anlatılmak istenen nedir?', 'Yeni bir dünyaya, yeni düşüncelere yol açmak', ['Okurun evine misafir olarak gitmek', 'Kütüphanenin kapısını açık bırakmak', 'Kitabın kapağını açıp ilk sayfasını yüksek sesle okumak'], 'Kitabın okura bir kapı aralaması, ona yeni bilgi ve düşünce dünyalarının yolunu açması demektir.'),
  ('"Ne kadar istese de yaşlı adam, eski günlerin tadını bir daha bulamadı." cümlesinde anlatılan duygu hangisidir?', 'Geçmişe duyulan özlem', ['Geleceğe duyulan umut', 'Birine duyulan öfke', 'Başarıdan doğan gurur'], 'Eski günlerin tadını aramak ama bulamamak, geçmişe duyulan özlemi anlatır.'),
  ('"Dikkat et, merdivenin basamakları ıslak!" cümlesinde konuşanın amacı nedir?', 'Uyarmak', ['Rica etmek', 'Övmek', 'Tahmin yürütmek'], 'Konuşan, karşısındakini ıslak basamaklar konusunda bir tehlikeye karşı uyarmaktadır.'),
  ('"Rica etsem pencereyi biraz aralar mısınız?" cümlesi hangi anlamı taşır?', 'Kibar bir istek', ['Sert bir emir', 'Gizli bir tehdit', 'Bir yakınma ve sitem'], '"Rica etsem" ve soru biçimi, isteğin nazikçe dile getirildiğini gösterir.'),
  ('Bir annenin çocuğuna söylediği aşağıdaki sözlerden hangisi buyruk niteliğindedir?', 'Hemen odanı topla ve ödevlerini bitir.', ['Odanı toplarsan çok sevinirim.', 'Keşke odamı zamanında toplasaydım.', 'Odasını toplamış, ödevlerini bitirmiş.'], 'Emir kipiyle kurulmuş "topla" ve "bitir" yüklemleri, konuşanın kesin bir buyruk verdiğini gösterir.'),
  ('"Bu kadar zaman geçti, bir kez olsun arayıp hâlimi sormadın." cümlesinde hangi duygu dile getirilmiştir?', 'Sitem', ['Özlem', 'Umut', 'Övünç ve gurur'], 'Sevilen birine, ilgisizliği yüzünden kırgınlıkla seslenmek sitemdir.'),
  ('"Belki bir gün yeniden o eski bahçede, aynı ağacın altında oturur sohbet ederiz." cümlesinde hangi duygu vardır?', 'Umut', ['Pişmanlık', 'Öfke', 'Korku'], '"Belki bir gün" sözüyle gelecekte gerçekleşmesi istenen bir dileğe umutla bakılmaktadır.'),
  ('"Bayram sabahları ninemin pişirdiği çöreklerin kokusunu hâlâ arıyorum." cümlesinde ağır basan duygu hangisidir?', 'Özlem', ['Sitem', 'Kıskançlık', 'Şaşkınlık'], 'Geçmişteki bir kokuyu hâlâ aramak, o günlere duyulan özlemi anlatır.'),
  ('"Annem, akşam yemeğine misafir geleceğini söyledi." cümlesi için hangisi doğrudur?', 'Başkasının sözü dolaylı olarak aktarılmıştır.', ['Başkasının sözü hiç değiştirilmeden aktarılmıştır.', 'Cümlede bir tahmin yürütülmüştür.', 'Cümlede bir öneri vardır ve hemen uygulanmalıdır.'], 'Annenin sözü, aktaranın cümlesine "geleceğini söyledi" biçiminde katılmıştır; bu dolaylı anlatımdır.'),
  ('"Yolun sonunda ne olursa olsun, yürümeye devam edeceğim." cümlesinde hangi tutum vardır?', 'Kararlılık', ['Kararsızlık', 'Pişmanlık', 'Hayıflanma'], '"Ne olursa olsun" sözü, sonuç ne olursa olsun eylemden vazgeçilmeyeceğini bildirir; bu kararlılıktır.'),
  ('"Ağacın en yüksek dalına bir kuş konmuştu." cümlesinde "dal" sözcüğü hangi anlamdadır?', 'Gerçek anlam', ['Mecaz anlam', 'Yan anlam', 'Terim anlam'], 'Dal, ağacın gövdesinden ayrılan kol demektir; cümlede ilk ve temel anlamıyla kullanılmıştır.'),
  ('"Hasta, ameliyattan sonra yoğun bakıma alındı." cümlesindeki "yoğun bakım" sözü hangi alana özgü bir terimdir?', 'Tıp', ['Hukuk', 'Spor', 'Müzik'], 'Yoğun bakım, ağır hastaların sürekli izlendiği hastane birimini anlatan bir tıp terimidir.'),
  ('"Kuraklık yüzünden çiftçilerin yüzü asık, gelecek kaygısı büyüktü." cümlesinde "yüzü asık" sözü neyi anlatır?', 'Üzgün ve keyifsiz olmayı', ['Yüzünü yıkamamış olmayı', 'Yüzüne bir yara almayı', 'Herkese gülümseyerek bakmayı'], '"Yüzü asık" deyimi, üzüntü ya da kızgınlık nedeniyle keyifsiz görünmeyi anlatır.'),
  ('İçinde bir şey bulunmama niteliğini anlatan "boş" sıfatı, hangi cümlede değersiz ve anlamsız olma anlamına kaymıştır?', 'Bu boş laflarla kimseyi kandıramazsın.', ['Bardak boş kalınca yeniden doldurdu.', 'Otoparkta tek bir boş yer bile yoktu.', 'Boş kutuları geri dönüşüm kutusuna attı.'], '"Boş laf", anlamsız, değersiz söz anlamında mecazdır. Diğerlerinde içi dolu olmama anlamı vardır.'),
  ('Dokunma duyusuyla algılanan "yumuşak" niteliği, hangi cümlede yalnızca bu duyuyla ilgili ilk anlamıyla yer almıştır?', 'Kedinin yumuşak tüylerini okşadı.', ['Yumuşak bir sesle konuşmaya başladı.', 'Bu kış öteki yıllara göre yumuşak geçti.', 'Müdür, yumuşak tavrıyla herkesi sakinleştirdi.'], 'Tüylerin yumuşaklığı dokunma duyusuyla algılanır; bu, sözcüğün gerçek anlamıdır.'),
  ('"Işık" sözcüğü aşağıdakilerin hangisinde "yol gösteren, aydınlatıcı kişi ya da düşünce" anlamındadır?', 'Öğretmenimiz, karanlık yıllarımızda bize ışık oldu.', ['Odanın ışığını kapatıp uyudu.', 'Güneş ışığı perdenin arasından süzülüyordu.', 'Kırmızı ışıkta beklemeyen sürücüye trafik polisi ceza yazdı.'], 'Birine ışık olmak, ona yol göstermek, onu aydınlatmak demektir; mecaz anlamdır.'),
  ('"Sınavda çıkan sorular beklediğimden çok daha hafifti." cümlesinde "hafif" sözcüğü hangi anlamda kullanılmıştır?', 'Kolay, zorlamayan', ['Ağırlığı az olan', 'Rengi açık olan', 'Sesi alçak, zor duyulan'], 'Soruların ağırlığı tartılamaz; "hafif" burada kolay anlamında mecazdır.'),
  ('"Dedem, köyde herkesin saygı duyduğu, sözü dinlenen bir ihtiyardı." cümlesindeki "ihtiyar" sözcüğünün yerine anlam değişmeden hangisi kullanılabilir?', 'yaşlı', ['genç', 'zengin', 'çalışkan biri'], '"İhtiyar" ile "yaşlı" eş anlamlıdır.'),
  ('"Bu konuda verdiğin cevap beni hiç tatmin etmedi." cümlesindeki "cevap" sözcüğünün Türkçe kökenli eş anlamlısı hangisidir?', 'yanıt', ['soru', 'sınav', 'tartışma ve düşünce'], '"Cevap" Arapça kökenlidir; Türkçe karşılığı "yanıt"tır.'),
  ('"Zor" sözcüğünün karşıtı aşağıdaki cümlelerin hangisinde kullanılmıştır?', 'Bu bulmacayı çözmek sandığımdan çok kolaymış.', ['Bu bulmacayı çözmek gerçekten güçtü, saatlerimi aldı.', 'Bulmacanın son sorusu biraz çetrefilliydi.', 'Bulmacayı çözmek için saatlerce uğraştım.'], '"Kolay", "zor"un karşıtıdır. "Güç" ve "çetrefil" ise zora yakın anlamlıdır.'),
  ('"Bu kumaş ince ama dayanıklıdır." cümlesinde "ince" sözcüğünün karşıtı olarak hangisi kullanılabilir?', 'kalın', ['sağlam', 'yumuşak', 'renkli'], 'Kumaşın inceliği kalınlığının az olmasıdır; karşıtı "kalın"dır.'),
  ('"Bin" sözcüğü hangi cümlede sayı adı olarak değil, bir eylem olarak kullanılmıştır?', 'Otobüs kalkmak üzere, hemen bin!', ['Bu kütüphanede bin kitap var.', 'Bin yıllık bir çınarın altında oturduk.', 'Bin bir emekle bu evi yaptık.'], '"Binmek" eyleminin emir biçimi olan "bin", sayı adı "bin" ile sesteştir.'),
  ('Aşağıdaki gruplardan hangisinde sözcükler özelden genele doğru sıralanmıştır?', 'Ankara - Türkiye - Asya - Dünya', ['Dünya - Asya - Türkiye - Ankara', 'Türkiye - Ankara - Dünya - Asya kıtası', 'Asya - Ankara - Dünya - Türkiye'], 'Ankara\'dan Dünya\'ya doğru her kavram bir öncekini kapsar; sıra özelden geneledir.'),
  ('"Mobilya" sözcüğüne göre özel anlamlı olan sözcük hangisidir?', 'dolap', ['eşya', 'ev', 'malzeme'], 'Dolap, mobilyanın bir türüdür; mobilya ise dolabı da kapsayan genel bir kavramdır.'),
  ('"Çöl gemisi" dolaylamasıyla anılan hayvan hangisidir?', 'Deve', ['At', 'Fil', 'Katır'], 'Çölde yük ve yolcu taşıdığı için deveye "çöl gemisi" denir.'),
  ('"Eli kulağında" deyimi hangi anlamı taşır?', 'Gerçekleşmesi çok yakın olan', ['Çok uzak bir gelecekte olacak olan', 'Kimsenin duymadığı bir haber', 'Elini kulağına götürüp dinleyen'], '"Eli kulağında", olması çok yakın, neredeyse gelmiş anlamına gelir: "Bayram eli kulağında."'),
  ('"Burnu havada" diye nitelenen biri için hangisi söylenebilir?', 'Kendini başkalarından üstün gören, kibirli biridir.', ['Çok iyi koku alabilen biridir.', 'Her zaman başı yukarıda, gökyüzüne bakarak yürüyen biridir.', 'Herkese yardım eden alçakgönüllü biridir.'], 'Deyim, kibirli ve kendini beğenmiş kişileri anlatır.'),
  ('"Dilinde tüy bitmek" deyimi hangi durumu anlatır?', 'Aynı şeyi defalarca söylemekten bıkmak', ['Hastalık nedeniyle konuşamamak', 'Yalan söylediği için utanmak', 'Çok yemek yemek ama bir türlü doymamak'], 'Bir şeyi tekrar tekrar söyleyip yorulmayı, bıkmayı anlatır.'),
  ('"Ateş pahası" sözü bir mal için kullanıldığında ne anlatılır?', 'Malın çok pahalı olduğu', ['Malın ateşte kolayca yandığı', 'Malın çok ucuza satıldığı', 'Malın sıcakken satılması gerektiği'], '"Ateş pahası", fiyatı çok yüksek demektir.'),
  ('"Can kulağıyla dinlemek" deyiminin anlatmak istediği nedir?', 'Büyük bir dikkatle dinlemek', ['Dinliyormuş gibi yapmak', 'Yarım kulakla, ilgisizce dinlemek', 'Bir sırrı başkalarından gizlemek'], 'Bütün dikkatini vererek, çok istekli biçimde dinlemeyi anlatır.'),
  ('"Annesi, yemeğe ... kardeşime \'Beğenmiyorsan aç kal.\' dedi." cümlesinde boşluğa hangi deyim uygun düşer?', 'burun kıvıran', ['el atan', 'göz koyan', 'kulak verip dinleyen'], '"Burun kıvırmak", bir şeyi beğenmemek, küçümsemektir; annenin cevabı bu tutuma yöneliktir.'),
  ('"Yeni okuluna ... biraz zaman gerekti ama sonunda arkadaşlarıyla çok iyi anlaştı." cümlesinde boşluğa hangisi getirilmelidir?', 'ayak uydurmak için', ['ayak diremek için', 'ayağı kaymak için', 'ayaklarına kapanmak için'], '"Ayak uydurmak", yeni bir ortama ya da duruma uyum sağlamaktır.'),
  ('"Ağzından kaçırmak" deyimi aşağıdaki durumlardan hangisine uygundur?', 'Sürpriz doğum günü partisini yanlışlıkla arkadaşına söyleyen Ege', ['Sıcak çorbasını çok hızlı içtiği için ağzı ve boğazı yanan Ece', 'Bir sözü yüksek sesle tekrar eden Mert', 'Hiç konuşmadan arkadaşını dinleyen Ada'], 'Deyim, söylememesi gereken bir şeyi istemeden söylemeyi anlatır.'),
  ('"Komşumuzun oğlu, çalışkanlığı ve dürüstlüğüyle kısa sürede patronunun gözüne girdi." cümlesindeki deyimin anlamı nedir?', 'Birinin sevgi ve güvenini kazanmak', ['Birinin gözüne toz ya da bir şey kaçmak', 'Birini kıskandırmak', 'Birinin gözünden kaçmak'], '"Göze girmek", beğenilip sevilmek, güven kazanmaktır.'),
  ('"Yüz çevirmek" deyiminin anlamca en yakın karşılığı hangisidir?', 'ilgisini kesmek', ['birine gülümsemek', 'yüzünü yıkamak', 'birini ziyaret etmek'], '"Yüz çevirmek", birinden ya da bir şeyden ilgisini çekmek, onu terk etmektir.'),
  ('"İşleyen demir ışıldar." atasözünün öğüdü nedir?', 'Sürekli çalışan kişi gelişir ve değer kazanır.', ['Demir eşyalar her gün parlatılmalıdır.', 'Çalışmak insanı yorar ve yıpratır.', 'Pahalı eşyalar ucuz olanlardan her zaman daha dayanıklıdır.'], 'Kullanılan demirin paslanmayıp parlaması gibi, çalışan insanın da yeteneklerini geliştirdiği anlatılır.'),
  ('"Acele işe şeytan karışır." atasözü hangi davranışa karşı uyarır?', 'Bir işi düşünmeden, aceleyle yapmaya', ['Bir işi gereğinden çok yavaş, ağırdan alarak yapmaya', 'Bir işi başkasına bırakmaya', 'Bir işe hiç başlamamaya'], 'Atasözü, aceleyle yapılan işlerde yanlışlıklar olacağını anlatarak dikkatli olmayı öğütler.'),
  ('"Gülü seven dikenine katlanır." atasözü hangi düşünceyi işler?', 'Sevilen bir şeyin zorluklarına da razı olmak gerekir.', ['Güller dikenli oldukları için koparılmamalıdır.', 'Sevdiklerimize karşı gerektiğinde sert ve ödün vermeyen biri olmalıyız.', 'Her güzelliğin bir bedeli olmayabilir.'], 'Bir şeyi isteyen, onun getirdiği sıkıntıları da göze almalıdır.'),
  ('"Söz gümüşse sükût altındır." atasözüne göre hangisi doğrudur?', 'Bazı durumlarda susmak konuşmaktan daha değerlidir.', ['Gümüş ve altın aynı değerdedir.', 'Her durumda konuşmak susmaktan çok daha iyidir ve yararlıdır.', 'Konuşmayanlar zengin olur.'], 'Atasözü, yerinde susmanın değerini anlatır; sükût sessizlik demektir.'),
  ('"Tatlı dil yılanı deliğinden çıkarır." atasözünün anlamına en yakın cümle hangisidir?', 'Güzel ve yumuşak sözlerle en zor insanlar bile ikna edilebilir.', ['Yılanlar tatlı yiyeceklere düşkündür.', 'İnsanları ikna etmek için her zaman sert ve kararlı olmak gerekir.', 'Çok konuşan, sonunda başını derde sokar.'], 'Atasözü, nazik konuşmanın en inatçı kişiyi bile yumuşatacağını anlatır.'),
  ('"Bin bilsen de bir bilene danış." atasözü aşağıdakilerden hangisini öğütler?', 'Ne kadar bilgili olursak olalım başkalarının görüşünü almayı', ['Bilgili insanlarla tartışmaktan kaçınmayı', 'Hiç kimseye danışmadan, yalnızca kendi bilgisine güvenerek karar vermeyi', 'Bin tane kitap okumadan konuşmamayı'], 'Atasözü, bilginin sınırsız olmadığını, danışmanın her zaman yarar sağlayacağını anlatır.'),
  ('"Bayram sabahı çoluk çocuk hep birlikte dedemin evine gittik." cümlesindeki "çoluk çocuk" ikilemesi hangi anlamı karşılar?', 'Ailenin bütün bireyleri', ['Yalnızca küçük çocuklar', 'Mahalledeki bütün komşular ve tanıdıklar', 'Sadece evin yetişkinleri'], '"Çoluk çocuk", bir ailenin büyük küçük bütün bireylerini kapsayan bir topluluk anlamı taşır.'),
  ('"Düğüne konu komşu herkes gelmişti." cümlesinde "konu komşu" ikilemesi hangi anlamı karşılar?', 'Yakın çevrede oturanların tümü', ['Yalnızca bir aile', 'Uzak şehirlerden gelen misafirler', 'Düğünü düzenleyen kişiler'], '"Konu komşu", çevrede oturan bütün komşuları kapsayan bir topluluk anlamı taşır.'),
  ('"Kardeşim, kimse uyanmasın diye parmaklarının ucuna basarak yürüdü." cümlesinde kardeşimin davranışının amacı nedir?', 'Evdekilerin uykusunu bölmemek', ['Yürürken ayaklarını üşütmemek', 'Daha hızlı yürüyebilmek', 'Ayakkabılarını kirletmemek ve temiz tutmak'], '"Kimse uyanmasın diye" ifadesi, davranışın amacını, evdekilerin uyanmamasını belirtir.'),
  ('"Komşunun bahçesindeki ağaç, bizimkinden daha önce çiçek açtı." cümlesinde iki ağaç hangi yönden karşılaştırılmıştır?', 'Çiçek açma zamanı', ['Boyları', 'Meyvelerinin tadı', 'Yapraklarının rengi ve sayısı'], '"Daha önce" sözü, karşılaştırmanın zaman yönünden yapıldığını gösterir.'),
  ('"Van Gölü, Türkiye\'nin yüzölçümü en büyük gölüdür." yargısıyla ilgili hangisi doğrudur?', 'Ölçümle doğrulanabildiği için nesneldir.', ['Kişisel bir beğeni bildirdiği için özneldir.', 'Bir tahmine dayandığı için kesin değildir.', 'Bir öneri bildirdiği için uygulanmalıdır.'], 'Göllerin yüzölçümleri ölçülebilir; bu nedenle yargı herkes için aynıdır ve nesneldir.'),
  ('Aşağıdaki cümlelerden hangisi diğerlerinden farklı olarak öznel bir yargı içerir?', 'Bu şarkıcının sesi, dinleyeni alıp başka diyarlara götürüyor.', ['Şarkıcının ilk albümü 1998 yılında çıktı.', 'Albümde on iki şarkı bulunuyor.', 'Şarkıcı, konserlerini genellikle yaz aylarında açık hava sahnelerinde veriyor.'], 'Sesin dinleyeni başka diyarlara götürmesi kişisel bir izlenimdir; diğerleri doğrulanabilir bilgilerdir.'),
  ('"Gökyüzü bulutlanmaya başladı; akşama doğru yağmur yağabilir." cümlesinde yağmurla ilgili yargı nasıl bildirilmiştir?', 'Olasılık olarak', ['Kesin bir bilgi olarak', 'Bir yakınma olarak', 'Bir pişmanlık olarak'], '"Yağabilir" yapısı, yağmurun gerçekleşmesinin olası olduğunu ama kesin olmadığını anlatır.'),
  ('"Yine mi bu dizinin aynı bölümünü izliyorsun?" cümlesinden hangisi örtülü olarak anlaşılır?', 'Bu bölüm daha önce de izlenmiştir.', ['Dizi ilk kez yayımlanmaktadır.', 'Konuşan, diziyi çok beğenmekte ve her bölümünü izlemektedir.', 'Bölüm henüz hiç izlenmemiştir.'], '"Yine" ve "aynı bölüm", bu bölümün önceden de izlendiğini sezdirir.'),
  ('"Ön yargı" kavramını en iyi açıklayan seçenek hangisidir?', 'Bir kişi ya da şey hakkında, onu tanımadan önceden edinilmiş yargı', ['Bir olayın, gerçekleşmeden önce elde bulunan verilere göre tahmin edilmesi', 'Bir kişiye önceden teşekkür edilmesi', 'Bir kararın uzun düşünme sonucunda verilmesi'], 'Ön yargı, deneyim ve bilgiye dayanmadan önceden edinilmiş olumlu ya da olumsuz kanıdır.'),
  ('"Bu yemeği o kadar çok sevdim ki her gün yesem bıkmam." cümlesinde abartmanın işlevi nedir?', 'Yemeğin ne kadar beğenildiğini vurgulamak', ['Yemeğin tarifini açıklamak', 'Yemeğin fiyatını eleştirmek', 'Yemeğin besin değerini ve kalorisini ölçmek'], '"Her gün yesem bıkmam" sözü, beğeninin derecesini abartarak vurgular.'),
  ('"Kalabalık yerlerde çantanı önünde taşırsan kendini daha güvende hissedersin." cümlesinde konuşanın yaptığı nedir?', 'Yol göstermek', ['Yakınmak', 'Alay etmek', 'Pişmanlığını dile getirmek'], 'Konuşan, karşısındakine nasıl davranırsa daha güvende olacağını söyleyerek öğüt vermektedir.'),
  ('"Gece yarısına kadar süren inşaat gürültüsü yüzünden haftalardır doğru dürüst uyuyamıyoruz." cümlesinin anlamca türü nedir?', 'Yakınma', ['Öneri', 'Tanım', 'Umut ve beklenti'], 'Konuşan, uzun süredir yaşadığı uykusuzluktan ve gürültüden şikâyet etmektedir.'),
  ('"Çocukken dedemin anlattığı hikâyeleri kaydetmediğim için şimdi çok üzülüyorum." cümlesinde hangi duygu vardır?', 'Pişmanlık', ['Övünç', 'Merak', 'Sitem ve kırgınlık'], 'Geçmişte yapılmayan bir davranış yüzünden duyulan üzüntü pişmanlıktır.'),
  ('"Eli açık" sözü bir kişi için kullanıldığında ne kastedilir?', 'Cömert biri olduğu', ['Elinde yara olduğu', 'Elleri hep boş olduğu', 'Çok çalışkan biri olduğu'], '"Eli açık", parasını ve malını esirgemeyen, cömert kişi anlamındadır.'),
  ('"Annemin sesi, bir ninni gibi yumuşaktı." cümlesinde benzetme edatı hangisidir?', 'gibi', ['annemin', 'sesi', 'yumuşaktı'], '"Gibi", benzetmeyi kuran edattır; ses ninniye yumuşaklık yönünden benzetilmiştir.'),
  ('"Deniz, o gün öfkeyle kıyıları dövüyordu." cümlesinde denize hangi insani özellik yüklenmiştir?', 'Öfkelenme', ['Konuşup derdini anlatma', 'Gülme', 'Uyuma'], 'Öfke, insana özgü bir duygudur; denizin dalgaları öfkeli bir insanın davranışı gibi anlatılmıştır.'),
  ('"Gazete, güncel olayları ve haberleri belli aralıklarla okura ulaştıran basılı yayındır." cümlesinin anlatım amacı nedir?', 'Bir kavramı tanımlamak', ['Bir gazeteyi okura önermek', 'Gazetecileri eleştirmek', 'Gazete okumanın zararlarını anlatmak ve uyarmak'], 'Cümle, gazetenin ne olduğunu ve temel niteliklerini açıklar; bu bir tanımdır.'),
  ('"Bu şehirde yaşamak her geçen gün zorlaşıyor." cümlesiyle anlamca en yakın cümle hangisidir?', 'Bu şehirde hayat gittikçe güçleşiyor.', ['Bu şehirde yaşamak hep kolay oldu.', 'Bu şehir yaşamak için en uygun yer.', 'Bu şehre her gün yeni insanlar taşınıyor.'], '"Her geçen gün zorlaşıyor" ile "gittikçe güçleşiyor" aynı yargıyı bildirir.'),
  ('"Teknoloji hayatımızı kolaylaştırsa da ... ." cümlesinin anlamca en uygun tamamlanışı hangisidir?', 'bazı alışkanlıklarımızı olumsuz yönde değiştirdi', ['hayatımızı her yönden kolaylaştırdı', 'hiçbir işimize yaramadı, aksine hayatımızı her yönden zorlaştırdı', 'herkesin işini kolaylaştırdı'], '"-sa da" karşıtlık bildirir; kolaylaştırmanın karşısına olumsuz bir sonuç gelmelidir.'),
  ('"Ressam, eserlerinde doğayı olduğu gibi değil, onu nasıl hissettiyse öyle yansıtır." cümlesinden hangisi çıkarılabilir?', 'Ressam, doğayı kendi duyguları doğrultusunda resmeder.', ['Ressam, doğayı fotoğraf gibi birebir çizer.', 'Ressam, yalnızca insan yüzlerini konu alan portreler çizmektedir.', 'Ressam doğayı resmetmekten hoşlanmaz.'], '"Olduğu gibi değil, nasıl hissettiyse" ifadesi, ressamın doğayı öznel bir bakışla yansıttığını gösterir.'),
  ('"Kesmek" sözcüğü aşağıdakilerin hangisinde "durdurmak, sona erdirmek" anlamında kullanılmıştır?', 'Fırtına yüzünden elektrikler kesildi.', ['Annem pastayı sekiz dilime kesti.', 'Berber saçımı çok kısa kesmiş.', 'Kâğıdı makasla ikiye kesti.'], 'Elektriğin kesilmesi, akımın durması demektir; diğerlerinde bir nesneyi bölmek anlamı vardır.'),
  ('"Yakmak" eylemi aşağıdakilerin hangisinde mecaz anlamda kullanılmıştır?', 'Bu ayrılık, ikisinin de yüreğini yaktı.', ['Kamp ateşini yakmak için kuru dal topladık.', 'Ocağı yakıp çorbayı ısıttı.', 'Akşam olunca sokak lambalarını yaktılar.'], '"Yüreğini yakmak", derin bir acı vermek anlamında mecazdır.'),
  ('"Kalmak" sözcüğü aşağıdakilerin hangisinde "sınıf geçememek" anlamında kullanılmıştır?', 'Geçen yıl iki dersten kaldığı için sınıfı tekrarladı.', ['Tatilde iki hafta dedemlerde kaldık.', 'Yemekten geriye biraz pilav kaldı.', 'Toplantı yarına kaldı.'], 'Dersten kalmak, başarısız olup geçememektir. Diğerlerinde konaklamak, artmak ve ertelenmek anlamları vardır.'),
  ('"Okul müdürü, öğrencilerin sorunlarıyla bizzat ilgilendi." cümlesindeki "bizzat" sözcüğünün anlamı nedir?', 'kendisi, başkasına bırakmadan', ['sonradan, gecikerek', 'kısmen, yarım yamalak', 'başkaları aracılığıyla'], '"Bizzat", bir işi başkasına yaptırmadan kendisi yapmak anlamına gelir.'),
  ('"Uzun yürüyüşten sonra adımlarını sürüyerek eve vardı." cümlesindeki "adımlarını sürüyerek" sözünün anlamca en yakın karşılığı hangisidir?', 'çok yorgun bir biçimde', ['koşar adım ve neşeyle', 'dans ederek', 'hiç durmadan ve hızla'], 'Adımlarını sürümek, yorgunluktan ayaklarını zorla ilerletmektir.'),
  ('"Sorulara verdiği yanıtlar, konuyu derinlemesine kavradığını gösteriyordu." cümlesindeki "derinlemesine kavramak" sözünün anlamca en yakını hangisidir?', 'en ince ayrıntısına kadar anlamak', ['yüzeysel olarak bilmek', 'ezberleyip tekrarlamak', 'konuyu hiç merak etmemek'], '"Derinlemesine kavramak", bir konuyu tüm ayrıntılarıyla, temelinden anlamaktır.'),
  ('"Konferansta konuşmacının sesi o kadar alçaktı ki arka sıralardakiler hiçbir şey ... ." cümlesinde boşluğa getirilecek sözcük hangisidir?', 'duyamadı', ['göremedi', 'yazamadı', 'anlatamadı'], 'Alçak ses işitmeyle ilgilidir; arka sıradakilerin sesi duyamaması beklenir.'),
  ('"Eser, yazıldığı dönemin toplumsal yapısını gerçekçi bir biçimde ... ." cümlesini anlamca en iyi tamamlayan sözcük hangisidir?', 'yansıtıyor', ['gizliyor', 'bozuyor', 'unutuyor'], 'Bir eserin toplumsal yapıyı gerçekçi biçimde ortaya koyması "yansıtmak" ile anlatılır.'),
  ('Aşağıdaki cümlelerin hangisinde bir hayvan sesinin yansıması olan bir sözcük kullanılmıştır?', 'Kümesteki tavuklar sabaha kadar gıdakladı.', ['Kümesteki tavuklar sabah erkenden yumurtladı.', 'Tavuklar bahçede yem arıyordu.', 'Kümesin kapısını kapatmayı unutmuştuk.'], '"Gıdaklamak", tavuğun çıkardığı sesin yansımasından türemiş bir eylemdir.'),
  ('"Kaş yapayım derken göz çıkarmak" deyiminin anlamı hangisidir?', 'Bir şeyi düzeltmeye çalışırken daha da bozmak', ['Bir işi büyük bir ustalıkla tamamlamak', 'Güzelleşmek için süslenmek', 'Bir hatayı hemen fark etmek'], 'Deyim, iyi niyetle yapılan bir müdahalenin durumu daha kötü hâle getirmesini anlatır.'),
  ('"Komşu komşunun külüne muhtaçtır." atasözünün vurguladığı düşünce hangisidir?', 'İnsanlar en küçük şeyler için bile birbirlerine ihtiyaç duyar.', ['Komşular birbirinin işine karışmamalıdır.', 'Soba külleri komşuya verilmemelidir.', 'Komşuluk ilişkileri zamanla zayıflar.'], 'Atasözü, değersiz görünen kül için bile komşuya gerek duyulabileceğini söyleyerek dayanışmayı vurgular.'),
  ('"Bugünün işini yarına bırakma." atasözüne aykırı davranan kişi hangisidir?', 'Ödevini her seferinde son geceye erteleyen Mert', ['İşlerini planlı biçimde, her gün zamanında yapan Ayşe', 'Sabah erkenden kalkıp işine başlayan Deniz', 'Ödevini verildiği gün bitiren Can'], 'Atasözü, işleri ertelememeyi öğütler; ödevini sürekli erteleyen Mert buna aykırı davranır.'),
  ('"Yeryüzündeki bütün sular bir gün tükense" diye başlayan bir cümle nasıl bir anlam taşır?', 'Varsayım', ['Kesinlik', 'Tanım', 'Teşekkür'], '"Tükense" dilek-şart yapısıyla gerçek olmayan bir durum kabul edilmekte, yani varsayım kurulmaktadır.'),
  ('"İnsan doğduğu toprağı unutabilir mi hiç?" cümlesinin anlamca karşılığı hangisidir?', 'İnsan doğduğu toprağı unutamaz.', ['İnsan doğduğu toprağı kolayca unutur.', 'İnsanlar doğdukları yerde yaşamaz.', 'Doğduğu toprağı unutmak gerekir.'], 'Sözde soru biçimindeki cümle, yanıtı açık olan "unutamaz" yargısını vurgulamaktadır.'),
  ('"Bu kadar güzel bir manzaraya kim hayran kalmaz?" sorusunun anlamı hangisidir?', 'Bu manzaraya herkes hayran kalır.', ['Bu manzaraya kimse hayran kalmaz.', 'Manzaraya hayran kalanların sayısı bilinmez.', 'Manzaraya yalnızca turistler hayran kalır.'], 'Sözde soru, "kim ... kalmaz" yapısıyla herkesin hayran kalacağını vurgular.'),
  ('"Kırk yıllık dostunu bir sözle kırmak, ömür boyu sürecek bir pişmanlığa dönüştü." cümlesinden hangisi çıkarılabilir?', 'Söylenen bir söz uzun süreli bir pişmanlığa yol açmıştır.', ['Dostluk kısa süreli bir tanışıklıktır.', 'Konuşan dostunu hiç kırmamıştır.', 'Konuşan, kırk yıl boyunca dostunu bir kez bile kırmamıştır.'], 'Bir sözle dostu kırmanın ömür boyu süren bir pişmanlık yarattığı açıkça belirtilmiştir.'),
  ('"Tarihî eserler, geçmişle gelecek arasında köprü kurar." cümlesinde anlatılmak istenen nedir?', 'Tarihî eserler, geçmişin birikimini gelecek kuşaklara aktarır.', ['Tarihî eserler köprü yapımında kullanılır.', 'Tarihî eserler yalnızca müzelerde, cam vitrinler içinde sergilenmelidir.', 'Geçmiş ile gelecek arasında hiçbir bağ yoktur.'], '"Köprü kurmak" mecaz anlamda bağlantı sağlamaktır; eserler geçmişi geleceğe taşır.'),
  ('Aşağıdaki yargılardan hangisi kanıtlanabilir nitelikte değildir?', 'Bu şehrin insanları ülkenin en misafirperver insanlarıdır.', ['Bu şehir denizden yaklaşık iki yüz metre yüksektedir.', 'Şehrin merkezinden bir nehir geçmektedir.', 'Şehirde üç üniversite ve iki büyük halk kütüphanesi bulunmaktadır.'], 'Misafirperverlik ölçülemeyen, kişiden kişiye değişen bir değerlendirmedir; diğerleri doğrulanabilir bilgilerdir.'),
  ('"Hakem, son dakikada verdiği penaltıyla maçın kaderini değiştirdi." cümlesindeki "penaltı" sözcüğü hangi alana özgü bir terimdir?', 'Spor', ['Hukuk', 'Ekonomi ve ticaret', 'Tıp'], 'Penaltı, futbolda ceza alanındaki bir faul sonucu verilen atışı anlatan bir spor terimidir.'),
  ('"Pay" sözcüğü aşağıdaki cümlelerin hangisinde matematik terimi olarak kullanılmıştır?', 'Bir kesrin payı, paydasından küçükse kesir birden küçüktür.', ['Mirastan herkes eşit pay aldı.', 'Bu başarıda öğretmenlerin payı büyük.', 'Pastadan kardeşime de pay ayırdım.'], 'Matematikte pay, kesir çizgisinin üstündeki sayıdır. Diğerlerinde "hisse, katkı" anlamları vardır.'),
  ('"Bu şiirde uyak düzeni oldukça düzenli; her dörtlüğün ikinci ve dördüncü dizeleri uyaklı." cümlesindeki "dize" sözcüğü hangi alana aittir?', 'Edebiyat', ['Coğrafya', 'Müzik aletleri', 'Tıp'], 'Dize, şiirin her bir satırını anlatan bir edebiyat terimidir.'),
  ('"Sınırsız" sözcüğünün karşıt anlamlısı aşağıdakilerden hangisidir?', 'sınırlı', ['sonsuz', 'geniş', 'engin'], 'Sınırsız, bir sınırı olmayan; karşıtı belli bir sınırı olan "sınırlı"dır.'),
  ('"Verimli bir toplantı oldu; herkes fikirlerini rahatça söyledi." cümlesindeki "verimli" sözcüğünün karşıtı hangisidir?', 'verimsiz', ['yararlı', 'bereketli', 'başarılı'], 'Verimli, iyi sonuç veren; karşıtı "verimsiz"dir. Diğerleri verimliye yakın anlamlıdır.'),
  ('"Okul kütüphanesine çok sayıda yeni yapıt kazandırıldı." cümlesindeki "yapıt" sözcüğünün eş anlamlısı hangisidir?', 'eser', ['yapı', 'bina', 'kitaplık'], '"Yapıt", "eser" sözcüğünün Türkçe karşılığıdır.'),
  ('"Bu konuda daha fazla bilgi edinmek istiyorum." cümlesindeki "edinmek" sözcüğünün yerine anlamca hangisi gelebilir?', 'sahip olmak', ['kaybetmek', 'unutmak', 'yaymak'], '"Edinmek", bir şeyi elde etmek, sahip olmak anlamına gelir.'),
  ('"Yüz" sözcüğü aşağıdaki cümlelerin hangisinde sayı adı olarak kullanılmıştır?', 'Kitabın ilk yüz sayfasını bir günde okudum.', ['Gölde çocuklar yüzüyordu.', 'Yüzünde bir gülümseme belirdi.', 'Bu bardağın yüzü çatlak.'], '"Yüz" sözcüğü sayı, organ, yüzey ve "yüzmek" eyleminin kökü olarak sesteştir; ilk cümlede sayı anlamı vardır.'),
  ('"Lütfen kütüphanede yüksek sesle konuşmayalım, arkadaşlarımız ders çalışıyor." cümlesinde konuşanın tutumu nasıldır?', 'Kibar bir uyarıda bulunmaktadır.', ['Sert bir biçimde tehdit etmektedir.', 'Geçmişteki bir davranışından pişmanlık duymaktadır.', 'Bir olayı tarafsızca aktarmaktadır.'], '"Lütfen" sözü ve gerekçe gösterilmesi, uyarının nazik bir dille yapıldığını gösterir.'),
  ('"Ne çok sevmiştik o eski evi, şimdi yerinde koca bir apartman yükseliyor." cümlesinde hangi duygu ağır basmaktadır?', 'Geçmişe özlem ve hüzün', ['Geleceğe dönük heyecan', 'Bir kişiye öfke', 'Bir başarıdan duyulan gurur'], 'Eski evin sevildiği ve yerine apartman yapıldığı söylenerek kaybolan geçmişe duyulan özlem anlatılmıştır.'),
  ('"Sen de mi beni anlamadın, en yakın dostum?" cümlesinde hangi duygu dile getirilmektedir?', 'Sitem', ['Sevinç', 'Umut', 'Merak'], 'Yakın bir kişiye, beklentisini karşılamadığı için kırgınlıkla seslenilmektedir; bu sitemdir.'),
  ('Aşağıdaki cümlelerin hangisinde umut duygusu vardır?', 'Bu zor günler elbet geçecek, yeniden güleceğiz.', ['O günleri hatırlayınca hâlâ üzülüyorum.', 'Keşke o yolculuğa hiç çıkmasaydık.', 'Bunca emeğim boşa gitti, hiçbir şey kalmadı.'], 'Zor günlerin geçeceğine ve yeniden mutlu olunacağına duyulan inanç umuttur.'),
  ('"Bu çocuk o kadar hızlı koşuyor ki rüzgâr bile ona yetişemez." cümlesindeki anlatım için hangisi söylenebilir?', 'Hız, abartılarak anlatılmıştır.', ['Rüzgârın hızı ölçülerek verilmiştir.', 'Çocuğun yavaşlığı alaycı biçimde eleştirilmiştir.', 'Bir koşu yarışmasının sonucu nesnel olarak aktarılmıştır.'], 'Rüzgârın bile yetişemeyeceğini söylemek, çocuğun hızını abartmaktır.'),
  ('"Bu ev öyle küçük ki iki kişi aynı anda nefes alamıyor." cümlesinde hangi anlatım biçimine başvurulmuştur?', 'Abartma', ['Tanımlama', 'Kişileştirme', 'Benzetme edatıyla benzetme'], 'İki kişinin aynı anda nefes alamayacağı söylenerek evin küçüklüğü abartılmıştır.'),
  ('"Gençler, büyüklerinin deneyimlerinden yararlanmalı; ama onların yaptığı hataları tekrarlamamalı." cümlesinde ağır basan anlam hangisidir?', 'Öğüt', ['Yakınma', 'Pişmanlık', 'Alay'], 'Cümle, gençlere nasıl davranmaları gerektiğini "-malı" yapısıyla söyleyerek öğüt vermektedir.'),
  ('"Sergi, bazı eserlerin yetersiz ışıklandırılması nedeniyle izleyiciye hak ettiği etkiyi bırakamamış." cümlesinde eleştirilen nedir?', 'Sergideki ışıklandırma', ['Eserlerin konuları', 'Sanatçıların teknikleri', 'İzleyicilerin ilgisizliği'], 'Cümlede etkiyi azaltan neden olarak yetersiz ışıklandırma gösterilmiş ve eleştirilmiştir.'),
  ('"Annemin uyarılarını dinleseydim şimdi bu hastalıkla uğraşmazdım." cümlesinden hangisi çıkarılabilir?', 'Konuşan annesinin uyarılarını dikkate almamıştır.', ['Konuşan annesini her zaman dinlemiştir.', 'Konuşan hiç hastalanmamıştır.', 'Annesi ona hiçbir uyarıda bulunmamıştır.'], '"Dinleseydim" yapısı, uyarıların dinlenmediğini ve bundan pişmanlık duyulduğunu gösterir.'),
  ('"Bu yolculuğa çıktığıma hiç pişman değilim." cümlesinin anlamca en yakın karşılığı hangisidir?', 'Bu yolculuğa çıktığım için memnunum.', ['Bu yolculuğa çıktığım için çok üzgünüm.', 'Bu yolculuğa çıkıp çıkmamakta kararsızım.', 'Bu yolculuğa hiç çıkmadım.'], '"Pişman değilim" ifadesi, yapılan şeyden memnuniyet duyulduğunu anlatır.'),
  ('"Gerçek dost, yüzüne gülüp arkandan konuşan değil, yüzüne acı gerçeği söyleyendir." cümlesiyle hangi atasözü aynı düşünceyi paylaşır?', 'Dost acı söyler.', ['Ak akçe kara gün içindir.', 'Ağaç yaşken eğilir.', 'Damlaya damlaya göl olur.'], '"Dost acı söyler" atasözü, gerçek dostun hoşa gitmese de doğruyu söyleyeceğini anlatır.'),
  ('"Bu hafta o kadar yoğundu ki başımı kaşıyacak vaktim olmadı." cümlesinde "başını kaşıyacak vakti olmamak" sözüyle anlatılan nedir?', 'Çok meşgul olmak', ['Başının kaşınması', 'Saatini kaybetmek', 'Uzun süre dinlenmek'], 'Deyim, en küçük işe bile zaman ayıramayacak kadar yoğun olmayı anlatır.'),
  ('"Söylediklerinin hiçbiri gerçek değildi; hepsi uydurmaydı." cümlesindeki "uydurma" sözcüğünün anlamca en yakın karşılığı hangisidir?', 'asılsız', ['kanıtlanmış', 'belgelenmiş', 'doğrulanmış'], '"Uydurma", gerçeğe dayanmayan, asılsız demektir.'),
];
